CREATE TABLE IF NOT EXISTS profile (id INTEGER PRIMARY KEY, birth_date DATE NOT NULL, sex VARCHAR NOT NULL, height_cm DOUBLE NOT NULL, current_weight_kg DOUBLE NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS nutrition_targets (id INTEGER PRIMARY KEY, calories DOUBLE NOT NULL, protein_g DOUBLE NOT NULL, fat_g DOUBLE NOT NULL, carbs_g DOUBLE NOT NULL, valid_from DATE NOT NULL, valid_to DATE, note VARCHAR);
CREATE TABLE IF NOT EXISTS foods (id INTEGER PRIMARY KEY, name VARCHAR UNIQUE NOT NULL, kcal_100 DOUBLE NOT NULL, protein_100 DOUBLE NOT NULL, fat_100 DOUBLE NOT NULL, carbs_100 DOUBLE NOT NULL, barcode VARCHAR UNIQUE);
CREATE TABLE IF NOT EXISTS dishes (id INTEGER PRIMARY KEY, name VARCHAR UNIQUE NOT NULL, total_grams DOUBLE NOT NULL, total_kcal DOUBLE NOT NULL, total_protein DOUBLE NOT NULL, total_fat DOUBLE NOT NULL, total_carbs DOUBLE NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS meals (id BIGINT PRIMARY KEY, eaten_at TIMESTAMP NOT NULL, food_id INTEGER NOT NULL, grams DOUBLE NOT NULL, note VARCHAR, meal_type VARCHAR);
CREATE TABLE IF NOT EXISTS weights (measured_on DATE PRIMARY KEY, kg DOUBLE NOT NULL);
CREATE TABLE IF NOT EXISTS body_measurements (measured_on DATE PRIMARY KEY, weight_kg DOUBLE NOT NULL, body_fat_pct DOUBLE, muscle_pct DOUBLE, note VARCHAR);
CREATE TABLE IF NOT EXISTS supplements (id INTEGER PRIMARY KEY, name VARCHAR UNIQUE NOT NULL, default_amount DOUBLE, default_unit VARCHAR NOT NULL, active_ingredients VARCHAR, note VARCHAR);
CREATE TABLE IF NOT EXISTS supplement_intake (id BIGINT PRIMARY KEY, taken_at TIMESTAMP NOT NULL, supplement_id INTEGER NOT NULL, amount DOUBLE NOT NULL, unit VARCHAR NOT NULL, note VARCHAR);
CREATE TABLE IF NOT EXISTS daily_activity (activity_date DATE PRIMARY KEY, steps INTEGER NOT NULL DEFAULT 0, active_minutes INTEGER NOT NULL DEFAULT 0, note VARCHAR);
CREATE TABLE IF NOT EXISTS workouts (id BIGINT PRIMARY KEY, performed_at TIMESTAMP NOT NULL, workout_type VARCHAR NOT NULL, duration_min DOUBLE NOT NULL, intensity VARCHAR, calories_est DOUBLE, note VARCHAR);
